import assert from "node:assert/strict";
import { test } from "node:test";
import { toPortablePath } from "../src/paths.ts";

test("grader: toPortablePath", () => {
  assert.equal(toPortablePath("src\\lib\\a.ts"), "src/lib/a.ts");
  assert.equal(toPortablePath("./src//a.ts"), "src/a.ts");
  assert.equal(toPortablePath("src/"), "src");
  assert.equal(toPortablePath("a/./b"), "a/b");
  assert.throws(() => toPortablePath("../x"));
  assert.throws(() => toPortablePath("a/../b"));
  assert.throws(() => toPortablePath("C:\\x"));
  assert.throws(() => toPortablePath("/etc"));
});

