// path helpers for fixture files

export function toPortablePath(p: string): string {
  const slashed = p.replace(/\\/g, "/");
  if (slashed.startsWith("/") || /^[A-Za-z]:/.test(slashed)) {
    throw new Error(`absolute paths are not allowed: ${p}`);
  }
  const parts = slashed.split("/").filter((s) => s !== "" && s !== ".");
  if (parts.some((s) => s === "..")) throw new Error(`parent segments are not allowed: ${p}`);
  return parts.join("/");
}

